#!/usr/bin/env bash
# =============================================================
#  塔奥 thalvior · 多店铺电商 ERP — 自包含一键安装脚本
#  用法： sudo bash install.sh your-domain.com
#  本文件已内含全部程序，无需再上传其它任何东西
# =============================================================
set -euo pipefail

DOMAIN="${1:-}"
if [ -z "$DOMAIN" ]; then
  echo "用法: sudo bash install.sh your-domain.com"
  echo "例如: sudo bash install.sh thalvior.fun"
  exit 1
fi

if [ "$(id -u)" -ne 0 ]; then
  echo "请用 root 或 sudo 执行"; exit 1
fi

APP_DIR="/opt/thalvior"
echo "==> 域名: $DOMAIN"

# ---------- 1. 解压自身 ----------
echo "==> 展开程序文件到 $APP_DIR ..."
mkdir -p "$APP_DIR"
PAYLOAD_LINE=$(grep -n "^__THALVIOR_PAYLOAD__$" "$0" | cut -d: -f1)
tail -n +$((PAYLOAD_LINE + 1)) "$0" | base64 -d | tar -xz -C "$APP_DIR"
echo "    完成"

cd "$APP_DIR/thalvior"

# ---------- 2. 检查依赖 ----------
if ! command -v docker >/dev/null 2>&1; then
  echo "==> 未检测到 Docker，正在安装..."
  curl -fsSL https://get.docker.com | sh
  systemctl enable --now docker
fi
if ! docker compose version >/dev/null 2>&1; then
  echo "!! 缺少 docker compose 插件，请安装 docker-compose-plugin 后重试"
  exit 1
fi

# ---------- 3. 绑定域名 ----------
sed -i "s/YOUR_DOMAIN/$DOMAIN/g" deploy/nginx.conf
mkdir -p data deploy/certs
echo "==> nginx 已绑定 $DOMAIN"

# ---------- 4. 初始化演示数据 ----------
if [ ! -f data/erp.db ]; then
  echo "==> 首次部署，生成演示数据（约 30 秒）..."
  docker compose run --rm --entrypoint "python -m backend.seed" app \
    || echo "!! 初始化未成功，稍后可手动: cd $APP_DIR/thalvior && docker compose run --rm app python -m backend.seed"
else
  echo "==> 已有数据库，跳过初始化"
fi

# ---------- 5. 构建启动 ----------
echo "==> 构建镜像并启动（首次约 2-3 分钟）..."
docker compose up -d --build

# ---------- 6. 等健康检查 ----------
echo "==> 等待服务就绪..."
OK=0
for i in $(seq 1 45); do
  if curl -fsS "http://127.0.0.1/api/health" >/dev/null 2>&1; then OK=1; break; fi
  sleep 2
done

echo
echo "=============================================="
if [ "$OK" = "1" ]; then
  echo "  塔奥 thalvior 部署成功"
else
  echo "  服务已启动，但健康检查未通过，请查看日志："
  echo "    cd $APP_DIR/thalvior && docker compose logs -f app"
fi
echo "----------------------------------------------"
echo "  访问：     http://$DOMAIN"
echo "  健康检查： http://$DOMAIN/api/health"
echo "----------------------------------------------"
echo "  若打不开，确认三点："
echo "   1. 域名 A 记录 → 本机公网 IP（ping $DOMAIN 验证）"
echo "   2. 云厂商安全组放行 80（HTTPS 再加 443）"
echo "   3. 服务器内 ufw/iptables 未拦截：ufw allow 80/tcp"
echo "=============================================="
exit 0

__THALVIOR_PAYLOAD__
